/**
 * Two players on the same world must skim on the same water. One arrives through the staged
 * path (heights generated by the terrain worker, adopted by `rebuildSteps`) after a planet of
 * a different size; the other generated the world on the main thread. Their liquid heights,
 * surface rise and the Zorb's skim force must match, or a skipping Zorb's path differs
 * between them.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import { createWorld, initPhysics } from '../../src/core/physics'
import { params } from '../../shared/params'
import { ProceduralTerrain, configureWorldWater } from '../../src/world/terrain/ProceduralTerrain'
import { generateTerrain } from '../../src/world/terrain/generate'
import { HeightSampler, sealSeam } from '../../src/world/terrain/sampler'
import { createTerrainCollider } from '../../src/world/terrain/collider'
import { currentTerrainSettings } from '../../src/world/terrain/settings'
import { setWaterClock } from '../../src/world/water/seaWaves'
import { setWeatherClock } from '../../src/world/weather/wind'
import type { TerrainData } from '../../src/world/terrain/generate'
import { zorbRadius, zorbSize, zorbSkimAt, ZORB_DEFAULT_CAM_OFFSET, type SkimForce } from '../../src/vehicles/zorb'

type Shell = ProceduralTerrain & { seed: number; sampler: HeightSampler; generate(): TerrainData; rebuildSteps(token: number): Generator<unknown>; building: number; prepared: Map<string, unknown> }

beforeAll(async () => {
  await initPhysics()
  // Both clients on the room's clock: the waves and the wind that shapes the sea's swell.
  setWaterClock(() => 37.25)
  setWeatherClock(() => 37.25)
  // Past the swell's calm-and-rise after a clock change (seaWaves CLOCK_SWITCH_SECONDS).
  const real = performance.now.bind(performance)
  vi.spyOn(performance, 'now').mockImplementation(() => real() + 60_000)
})
afterAll(() => { vi.restoreAllMocks(); for (const id of ['terrain.planetSize', 'world.seaKind']) params.set(id, params.get(id)!.def.default) })

/** A ProceduralTerrain with only its simulation: no renderer, meshes or vegetation. */
function shell(data: TerrainData, seed: number): Shell {
  const world = createWorld(9.81)
  const quiet = new Proxy({}, { get: () => () => {} })
  const t = Object.create(ProceduralTerrain.prototype) as Shell
  Object.assign(t, {
    seed, data, sampler: new HeightSampler(data), look: quiet, game: { world }, collider: createTerrainCollider(world, data),
    listeners: new Set(), prepared: new Map(), preparing: new Map(), building: 0, serial: 0, version: 0,
    colliderX: 0, colliderZ: 0, ice: null, iceKey: '', iceTop: -Infinity, restSurface: 0, restGround: 0,
    bodies: { sea: { kind: 'sea', liquid: 'water', frozen: false }, inland: { kind: 'inland', liquid: 'water', frozen: false } },
  })
  return t
}

/** Heights, rise and skim force at points of open liquid, including either side of the seam. */
function sample(t: Shell) {
  const r = zorbRadius(zorbSize.value, ZORB_DEFAULT_CAM_OFFSET), size = t.size, out: SkimForce = { x: 0, y: 0, z: 0, share: 0, depth: 0 }
  const rows: number[][] = []
  for (let x = 0; x < size && rows.length < 40; x += size / 23) for (const z of [7, size / 3, size - 3]) {
    const kind = t.liquidKindAt(x, z)
    if (!kind) continue
    const surface = t.liquidHeightAt(x, z)
    const f = zorbSkimAt(t, kind, { x, y: surface + r - 0.2, z }, r, surface, { x: 25, y: -2, z: 5 }, 9.81, out)
    rows.push([x, z, surface, t.liquidVerticalSpeedAt(x, z), f.x, f.y, f.z, f.share])
  }
  return rows
}

describe('zorb skimming after entering a planet of another size', () => {
  it('matches between the worker path and the main thread', () => {
    params.set('world.seaKind', 1)
    // Where the staged player came from: a 2 km planet, with its water sized to it. The new
    // one is 3 km: waves fitted to a 1 km or 4 km tile also tile 2 km exactly, so a power of
    // two either side would hide water left sized to the old planet.
    params.set('terrain.planetSize', 1)
    const before = generateTerrain(3, currentTerrainSettings()); sealSeam(before)
    const staged = shell(before, 3)
    configureWorldWater(before.size, 3)
    params.set('terrain.planetSize', Math.log2(3))
    const settings = currentTerrainSettings()
    // The worker's answer, as terrainWorker.ts makes it, copied as a transfer would.
    const made = generateTerrain(7, settings), seam = sealSeam(made)
    staged.seed = 7
    staged.prepared.set(`7:${JSON.stringify(settings)}`, { data: structuredClone(made), seam, ms: 1 })
    staged.building = 1
    staged.rebuildSteps(1).next()
    expect(before.size).toBe(2048)
    expect(staged.size).toBe(3072)
    expect(staged.prepared.size).toBe(0)
    const fromWorker = sample(staged)

    const main = shell(before, 7)
    ;(main as { data: TerrainData }).data = main.generate()
    main.sampler.data = main.data
    const fromMain = sample(main)

    expect(fromWorker.length).toBeGreaterThan(5)
    // Some points must be skimming, or the force was never compared.
    expect(fromWorker.some((row) => row[7] > 0)).toBe(true)
    expect(fromWorker).toEqual(fromMain)
    // Generates a 2 km and two 3 km worlds: about 3 s on an idle machine, much more under load.
  }, 60_000)
})
